import os
import re
import sqlite3
import secrets
import logging
from functools import wraps

from flask import Flask, request, jsonify, g
from passlib.hash import pbkdf2_sha256

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
APP_SECRET = os.environ.get("APP_SECRET")
if not APP_SECRET:
    # Fallback so the app still runs; in production APP_SECRET must be set.
    APP_SECRET = secrets.token_hex(32)

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "db.sqlite3")

app = Flask(__name__)
app.config["SECRET_KEY"] = APP_SECRET

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


# ---------------------------------------------------------------------------
# Database helpers
# ---------------------------------------------------------------------------
def get_db():
    """Return a per-request sqlite connection."""
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        try:
            db.close()
        except Exception:  # pragma: no cover
            logger.exception("Error closing database")


def init_db():
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute("PRAGMA foreign_keys = ON")
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS invitations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                invite_id TEXT NOT NULL UNIQUE,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_name TEXT NOT NULL UNIQUE,
                email TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                invite_id TEXT NOT NULL UNIQUE,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (invite_id) REFERENCES invitations(invite_id)
            );
            """
        )
        conn.commit()
    finally:
        conn.close()


# ---------------------------------------------------------------------------
# Endpoints
# ---------------------------------------------------------------------------
@app.route("/invite_user", methods=["POST"])
def invite_user():
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({"message": "Invalid request body"}), 400

        email = data.get("email")
        if not isinstance(email, str) or not EMAIL_RE.match(email.strip()):
            return jsonify({"message": "Invalid email"}), 400

        email = email.strip().lower()

        db = get_db()

        # Reuse existing invitation if present (one invite per email).
        row = db.execute(
            "SELECT invite_id FROM invitations WHERE email = ?", (email,)
        ).fetchone()
        if row is not None:
            return (
                jsonify(
                    {
                        "invite_id": row["invite_id"],
                        "message": "Invitation already exists for this email.",
                    }
                ),
                200,
            )

        invite_id = secrets.token_urlsafe(32)
        try:
            db.execute(
                "INSERT INTO invitations (email, invite_id) VALUES (?, ?)",
                (email, invite_id),
            )
            db.commit()
        except sqlite3.IntegrityError:
            # Race condition: another request created it; fetch existing.
            db.rollback()
            row = db.execute(
                "SELECT invite_id FROM invitations WHERE email = ?", (email,)
            ).fetchone()
            if row is None:
                raise
            return (
                jsonify(
                    {
                        "invite_id": row["invite_id"],
                        "message": "Invitation already exists for this email.",
                    }
                ),
                200,
            )

        return (
            jsonify(
                {
                    "invite_id": invite_id,
                    "message": "Invitation created successfully.",
                }
            ),
            200,
        )
    except Exception:
        logger.exception("Error in /invite_user")
        return jsonify({"message": "Internal server error"}), 500


@app.route("/create_user", methods=["POST"])
def create_user():
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({"message": "Invalid request body"}), 400

        invite_id = data.get("invite_id")
        user_name = data.get("user_name")
        password = data.get("password")

        if not isinstance(invite_id, str) or not invite_id.strip():
            return jsonify({"message": "Invalid invite_id"}), 401
        if not isinstance(user_name, str) or not user_name.strip():
            return jsonify({"message": "Invalid user_name"}), 400
        if not isinstance(password, str) or len(password) < 8:
            return (
                jsonify({"message": "Password must be at least 8 characters."}),
                400,
            )

        invite_id = invite_id.strip()
        user_name = user_name.strip()

        db = get_db()

        inv = db.execute(
            "SELECT email FROM invitations WHERE invite_id = ?", (invite_id,)
        ).fetchone()
        if inv is None:
            return jsonify({"message": "Invalid invite_id"}), 401

        email = inv["email"]

        # Check username availability.
        existing = db.execute(
            "SELECT 1 FROM users WHERE user_name = ?", (user_name,)
        ).fetchone()
        if existing is not None:
            return (
                jsonify(
                    {
                        "message": "Username already exists. Try providing different username."
                    }
                ),
                400,
            )

        # Check whether this invitation was already used.
        used = db.execute(
            "SELECT 1 FROM users WHERE invite_id = ?", (invite_id,)
        ).fetchone()
        if used is not None:
            return jsonify({"message": "Invalid invite_id"}), 401

        password_hash = pbkdf2_sha256.hash(password)

        try:
            db.execute(
                "INSERT INTO users (user_name, email, password_hash, invite_id) "
                "VALUES (?, ?, ?, ?)",
                (user_name, email, password_hash, invite_id),
            )
            db.commit()
        except sqlite3.IntegrityError:
            db.rollback()
            return (
                jsonify(
                    {
                        "message": "Username already exists. Try providing different username."
                    }
                ),
                400,
            )

        return jsonify({"message": "User created"}), 200
    except Exception:
        logger.exception("Error in /create_user")
        return jsonify({"message": "Internal server error"}), 500


# ---------------------------------------------------------------------------
# Bootstrap
# ---------------------------------------------------------------------------
init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
